class AuditLog:
    def record(self, event: str, **fields) -> None:
        entry = {"event": event, "at": datetime.now(timezone.utc).isoformat(), **fields}
        logger.info(json.dumps(entry, sort_keys=True))

    def signup_blocked(self, ip: str, retry_after: int) -> None:
